// One review-only outfit from Denim_and_Everyday_Tops.png, rightmost column.
// Continuous shoulder/arm topology is fitted from the retained CC0 body surface;
// clothing has independent geometry, UVs, material, seams and construction details.
export const SQUARE_DENIM={id:'square-denim-v2',topHem:1.125,waist:1.105,cuff:.625,hem:.09,neckHalf:.108,neckBottom:1.387};
const clamp=T.MathUtils.clamp;let garmentAsset=null,garmentLoading=null;
export function loadSquareDenimAsset(){if(!garmentLoading)garmentLoading=new GLTFLoader().loadAsync(new URL('./assets/garments/Square_Denim_Blender.glb',import.meta.url).href).then(gltf=>{garmentAsset=[];gltf.scene.traverse(m=>{if(m.isSkinnedMesh)garmentAsset.push(m);});if(!garmentAsset.length)throw Error('Review garment asset has no skinned meshes');return true;}).catch(error=>{garmentLoading=null;throw error;});return garmentLoading;}

function neckline(p){const [x,y,z]=p;const front=clamp((z+.065)/.08,0,1),half=.078+front*.03,bottom=1.473-front*.086,r=.012;const qx=Math.abs(x)-(half-r),qy=bottom+r-y;return Math.hypot(Math.max(qx,0),Math.max(qy,0))+Math.min(Math.max(qx,qy),0)-r;}
function interpolate(a,b,t){const weight=new Map();for(const [v,f] of [[a,1-t],[b,t]])for(let k=0;k<4;k++)weight.set(v.j[k],(weight.get(v.j[k])||0)+v.w[k]*f);const best=[...weight].sort((a,b)=>b[1]-a[1]).slice(0,4),sum=best.reduce((s,p)=>s+p[1],0);return {p:a.p.map((n,i)=>n+(b.p[i]-n)*t),n:a.n.map((n,i)=>n+(b.n[i]-n)*t),uv:a.uv.map((n,i)=>n+(b.uv[i]-n)*t),j:Array.from({length:4},(_,i)=>best[i]?.[0]||0),w:Array.from({length:4},(_,i)=>(best[i]?.[1]||0)/sum)};}
