 function attach(g,m,name){const mesh=new T.SkinnedMesh(own(g),m);mesh.name=name;mesh.bind(body.skeleton,body.bindMatrix);mesh.frustumCulled=false;mesh.castShadow=mesh.receiveShadow=true;mesh.userData.exactOutfitCandidate=SQUARE_DENIM.id;rig.add(mesh);meshes.push(mesh);return mesh;}
 const top=triangles(fitSource,(poly,out)=>{for(const f of topPlanes){poly=clip(poly,f);if(poly.length<3)return;}triangulate(poly,out,v=>{v.base=[...v.p];const normal=new T.Vector3(...v.n).normalize();const elbow=Math.exp(-Math.pow((Math.abs(v.p[0])-.39)/.07,2));const ripple=Math.sin(Math.abs(v.p[0])*210+v.p[2]*12)*.0014*elbow;v.p=v.p.map((n,k)=>n+normal.getComponent(k)*(.007+ripple));if(Math.abs(v.base[1]-SQUARE_DENIM.topHem)<1e-5)v.p[1]=SQUARE_DENIM.topHem;v.uv=[v.p[0]*3+1.5,v.p[1]*3];return v;});},true);const topGeo=geometry(top);smoothNormals(topGeo);attach(topGeo,knit,'square-neck-top-continuous-shoulders');
 function projectJeans(v){const [x,y,z]=v.p;if(y>.94){const influences=new Map(),amount=clamp((y-.94)/.09,0,1);for(let k=0;k<4;k++){const joint=v.j[k],weight=v.w[k],transfer=thighIndices.has(joint)?weight*amount:0;influences.set(joint,(influences.get(joint)||0)+weight-transfer);influences.set(pelvisIndex,(influences.get(pelvisIndex)||0)+transfer);}const list=[...influences].sort((a,b)=>b[1]-a[1]).slice(0,4),sum=list.reduce((n,p)=>n+p[1],0);v.j=Array.from({length:4},(_,k)=>list[k]?.[0]||0);v.w=Array.from({length:4},(_,k)=>(list[k]?.[1]||0)/sum);}const side=x<0?-1:1,center=.116*side,centerZ=y<.5?-.079+(y-.09)/.41*.035:-.044+(y-.5)/.35*.018;const theta=Math.atan2(x-center,z-centerZ);if(y<.84){const low=clamp((.84-y)/.04,0,1),rX=.105+.009*Math.exp(-Math.pow((y-.19)/.09,2)),rZ=.108;const fold=Math.sin(y*105+theta*2)*.006*Math.exp(-Math.pow((y-.17)/.09,2))+Math.sin(y*80-theta*3)*.0025*Math.exp(-Math.pow((y-.53)/.1,2));const nx=center+Math.sin(theta)*Math.min(.108,rX+fold),nz=centerZ+Math.cos(theta)*(rZ+fold);v.p[0]=x+(nx-x)*low;v.p[2]=z+(nz-z)*low;}else{const rows=[[.84,.214,.13,-.03],[.93,.204,.132,-.035],[1,.177,.124,-.033],[1.105,.14,.094,.002]];let a=rows[0],b=rows.at(-1);for(let i=1;i<rows.length;i++)if(y<=rows[i][0]){a=rows[i-1];b=rows[i];break;}const f=clamp((y-a[0])/(b[0]-a[0]),0,1),rx=a[1]+(b[1]-a[1])*f,rz=a[2]+(b[2]-a[2])*f,cz=a[3]+(b[3]-a[3])*f,t=Math.atan2(x,z-cz),blend=clamp((y-.84)/.04,0,1);v.p[0]=(x+v.n[0]*.009)*(1-blend)+Math.sin(t)*rx*blend;v.p[2]=(z+v.n[2]*.013)*(1-blend)+(cz+Math.cos(t)*rz)*blend;}
 const hipAngle=Math.atan2(v.p[0],v.p[2]+.035);let u=theta/(2*Math.PI)+.5,hipU=hipAngle/(2*Math.PI)+.5;while(hipU-u>.5)hipU--;while(hipU-u<-.5)hipU++;u+=(hipU-u)*clamp((y-.84)/.06,0,1);v.uv=[u,(y-SQUARE_DENIM.hem)/(SQUARE_DENIM.waist-SQUARE_DENIM.hem)];return v;}
 const trousers=triangles(fitSource,(poly,out)=>{poly=clip(poly,p=>p[1]-SQUARE_DENIM.hem);poly=clip(poly,p=>SQUARE_DENIM.waist-p[1]);if(poly.length<3)return;triangulate(poly,out,projectJeans);},true);const trouserGeo=geometry(trousers);smoothNormals(trouserGeo);attach(trouserGeo,jean,'washed-black-wide-leg-jeans');
 // Surface projection for actual bindings, hems, curved pocket mouths and fly.
