 const surface=new T.Mesh(trouserGeo,new T.MeshBasicMaterial({side:T.DoubleSide})),topSurface=new T.Mesh(topGeo,new T.MeshBasicMaterial({side:T.DoubleSide}));const ray=new T.Raycaster();
 function surfacePoint(x,y,back=false,top=false){ray.set(new T.Vector3(x,y,back?-1:1),new T.Vector3(0,0,back?1:-1));const hit=ray.intersectObject(top?topSurface:surface,false)[0];return [x,y,hit?hit.point.z+(back?-.002:.002):back?-.15:.11];}
