 const edges=new Map(),key=v=>v.map(n=>n.toFixed(5)).join(',');for(let i=0;i<top.length;i+=3)for(let a=0;a<3;a++){const one=top[i+a],two=top[i+(a+1)%3],ka=key(one.p),kb=key(two.p),k=ka<kb?ka+'|'+kb:kb+'|'+ka;if(!edges.has(k))edges.set(k,{a:one,b:two,n:0});edges.get(k).n++;}
 const boundary=[...edges.values()].filter(e=>e.n===1&&topPlanes.some(f=>Math.abs(f(e.a.base||e.a.p))<.0001&&Math.abs(f(e.b.base||e.b.p))<.0001));const bindingVertices=[];for(const e of boundary){const a=e.a,b=e.b;const mid=interpolate(a,b,.5),atCuff=Math.abs(mid.p[0])>.61;const offset=v=>{const n=new T.Vector3(...v.n).normalize();return {...v,p:v.p.map((x,i)=>x+n.getComponent(i)*.001)};};const a0=offset(a),b0=offset(b),a1=offset(a),b1=offset(b);for(const v of [a1,b1]){if(atCuff)v.p[0]-=Math.sign(v.p[0])*.009;else if(mid.p[1]<1.14)v.p[1]+=.009;else{v.p[0]+=Math.sign(v.p[0])*.004;v.p[1]-=.006;}}bindingVertices.push(a0,b0,a1,b0,b1,a1);}const bg=geometry(bindingVertices);smoothNormals(bg);attach(bg,binding,'neck-binding-cuffs-and-top-hem');
 // Double-stitched waistband follows the actual narrow fitted waist.
