  for(const x of [side*.066,side*.115]){const points=[surfacePoint(x,1.074),surfacePoint(x,1.09),surfacePoint(x,1.111)];seam(points,.0032,jean,'belt-loop');}
  // Inferred side/inseam continuation. No decorative back pockets invented.
