export const SQUARE_DENIM_COLOURS=Object.freeze({shirt:'#24252a',bottom:'#42413e'});
// Per-avatar cloned materials: changing this outfit never dyes another character.
export function setSquareDenimColours(model,colours={}){
 const values={...SQUARE_DENIM_COLOURS,...colours};
 for(const key of ['shirt','bottom'])if(!/^#[0-9a-f]{6}$/i.test(values[key]))throw Error('Invalid outfit colour: '+key);
 model.traverse(mesh=>{
  if(!mesh.userData.exactOutfitCandidate)return;
  const mat=mesh.material,slot=mat.userData.recolourSlot;
  if(slot==='shirt'||slot==='bottom'){mat.color.set(values[slot]);if(mat.name==='Jeans_Stitch')mat.color.lerp(new T.Color('#c8c1b1'),.12);}
 });
 model.userData.outfitColours={...values};
 return values;
}
